from __future__ import annotations


def merge_intervals(intervals: list[list[int]]) -> list[list[int]]:
    if not intervals:
        return []

    # Create a copy to ensure we do not modify the input list or its inner lists
    sorted_intervals = sorted([list(interval) for interval in intervals], key=lambda x: x[0])

    merged: list[list[int]] = []

    for current in sorted_intervals:
        if not merged:
            merged.append(current)
        else:
            last = merged[-1]
            # If current overlaps or touches the last interval
            if current[0] <= last[1]:
                last[1] = max(last[1], current[1])
            else:
                merged.append(current)

    return merged
